const req=$input.first().json;
const h=req.headers||{};
const supplied=h['x-iuc-agent-secret']||h['X-IUC-Agent-Secret']||'';
const expected=$vars.N8N_EVENT_SHARED_SECRET;
if(supplied!==expected) throw new Error('Invalid Student Concierge secret');
const e=req.body||req;
if(!e.referenceNo) throw new Error('referenceNo required');
return [{json:{...e,agentId:'STUDENT_CONCIERGE',executionId:'SC-'+e.referenceNo+'-'+(e.eventId||Date.now())}}];

const s=$input.first().json;
const d=s.documentReview||{};
const w=s.workflow||{};
const quality=String(d['AI Quality Status']||w['Document Quality Status']||'').toUpperCase();
const review=String(d['Review Status']||w['Document Review Status']||'').toUpperCase();
let requestedAction='';
let requestType='';
let count=0;

if(review==='INCOMPLETE'){
  let missing=[];
  try{missing=JSON.parse(String(d['Missing Documents JSON']||'[]'));}catch(_){}
  if(!Array.isArray(missing)||!missing.length) throw new Error('Document Review is INCOMPLETE but no missing document list is recorded');
  requestedAction='SEND_MISSING_DOCUMENT_REQUEST';
  requestType='MISSING_REQUIRED_DOCUMENT';
  count=missing.length;
}else if(quality==='FOLLOW_UP_REQUIRED'){
  let follow=[];
  try{follow=JSON.parse(String(d['AI Quality Follow-up JSON']||'[]'));}catch(_){}
  if(!Array.isArray(follow)||!follow.length) throw new Error('Quality follow-up is required but no replacement instruction is available');
  requestedAction='SEND_DOCUMENT_REPLACEMENT_REQUEST';
  requestType='QUALITY_REPLACEMENT';
  count=follow.length;
}else{
  throw new Error('Student Concierge document task has no valid missing/quality request state');
}

return [{json:{
  referenceNo:s.referenceNo,
  reviewStatus:review,
  qualityStatus:quality,
  requestedAction,
  requestType,
  requestedCount:count,
  verifiedBefore:true
}}];

const s=$input.first().json;
const d=s.documentReview||{};
const status=String(d['Replacement Request Status']||'').toUpperCase();
const requestType=String(d['Replacement Request Type']||'').toUpperCase();
const notify=String(d['Replacement Notification Status']||'').toUpperCase();
const before=$('Verify Replacement Need').item.json||{};
const gateway=$('Send Student Document Request').item.json||{};
if(status!=='AWAITING_STUDENT') throw new Error('Student document request verification failed: '+status);
if(requestType!==String(before.requestType||'').toUpperCase()) throw new Error('Request type verification failed: '+requestType);
if(!notify) throw new Error('Student notification status was not recorded');
return [{json:{
  ok:true,
  referenceNo:s.referenceNo,
  verified:true,
  requestType,
  requestStatus:status,
  notificationStatus:notify,
  requiresHuman:gateway.requiresHuman===true,
  waitingForStudent:true
}}];
